#include <flat_set>
#include <vector>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::flat_multiset<int> values;
    values.insert(2);
    values.emplace(1);
    values.emplace_hint(values.end(), 3);
    assert(values.count(2) == 1 && values.lower_bound(2) != values.end() &&
        values.upper_bound(2) != values.begin());
    std::flat_multiset<int> copy = values;
    assert(copy == values);
    copy.swap(values);
    std::swap(copy, values);
    std::flat_multiset deduced(std::vector<int>{1, 2});
    assert(deduced.size() == 2);
    std::flat_multiset<int> sorted{std::sorted_equivalent, std::vector<int>{1, 2}};
    assert(sorted.size() == 2);
}
